update public.help_articles
set steps = jsonb_set(steps::jsonb, '{3}', '{"title":"Use AI fill from job","detail":"In the RAMS editor header, AI fill from job now leads with the job''s description of works required. The dialog shows that works description in an editable box (with the dictation mic) — if the job has no usable description you are asked to type or dictate one before generating, so you never get a vague RAMS. Generation also ingests the job type and category, customer, site details including address, site notes and access information, plus outstanding defects, remedial items and the parts list, and pulls the matching blocks from your RAMS library. The draft method statement covers the described works step by step (isolation, drain-down, access, repair, reinstatement, testing) with hazards, controls and PAS 79 risk ratings that match those works. A Generated from list shows exactly what was used, and everything stays editable."}'::jsonb),
    last_updated = now()
where slug = 'rams';